import { resolve, dirname } from 'node:path';
import { createRequire } from 'node:module';
import { Console } from 'node:console';
import vm from 'node:vm';
import { SAM_LIB_PATH, SAM_LIB_SPECIFIERS } from './sam-lib.mjs';

