// The brief's rules, as invariants over one payment.
const UNIT = (a) => a === 1 || a === 2;

export const stateInvariants = [
  { name: 'captured-within-authorized', pred: (s) => s.captured <= s.authorized },
  { name: 'refunded-within-captured', pred: (s) => s.refunded <= s.captured },
  { name: 'voided-captured-nothing', pred: (s) => s.status !== 'voided' || (s.captured === 0 && s.refunded === 0) },
  { name: 'at-most-3-requests', pred: (s) => s.requests <= 3 },
  { name: 'pending-within-requests', pred: (s) => s.pending >= 0 && s.pending <= s.requests },
  { name: 'exists-iff-requested', pred: (s) => (s.status === 'none') === (s.requests === 0) },
  { name: 'authorized-is-a-unit', pred: (s) => s.status === 'none' || UNIT(s.authorized) },
  { name: 'nothing-moved-before-capture', pred: (s) => ['captured', 'refunded'].includes(s.status) || (s.captured === 0 && s.refunded === 0) },
  { name: 'captured-status-has-capture', pred: (s) => !['captured', 'refunded'].includes(s.status) || UNIT(s.captured) },
  { name: 'refunded-means-all-refunded', pred: (s) => s.status !== 'refunded' || s.refunded === s.captured },
  { name: 'captured-means-not-all-refunded', pred: (s) => s.status !== 'captured' || s.refunded < s.captured },
  { name: 'failed-only-after-3', pred: (s) => s.status !== 'failed' || s.requests === 3 },
];

const changed = (pre, post) => Object.keys(pre).some((k) => pre[k] !== post[k]);

export const transitionInvariants = [
  { name: 'authorized-amount-fixed', pred: (pre, a, d, post) => pre.status === 'none' || post.authorized === pre.authorized },
  { name: 'refunds-only-grow', pred: (pre, a, d, post) => post.refunded >= pre.refunded },
  { name: 'requests-step-by-one', pred: (pre, a, d, post) => post.requests - pre.requests <= 1 && post.requests >= pre.requests },
  {
    name: 'requests-only-from-authorize-or-timeout',
    pred: (pre, a, d, post) => post.requests === pre.requests || a === 'AUTHORIZE' || a === 'TIMED_OUT',
  },
  {
    name: 'provider-decides-only-authorizing',
    pred: (pre, a, d, post) =>
      !['authorized', 'declined'].includes(post.status) || post.status === pre.status || (pre.status === 'authorizing' && a === 'COMPLETE'),
  },
  { name: 'invalid-amount-changes-nothing', pred: (pre, a, d, post) => !('amount' in (d || {})) || UNIT(d.amount) || !changed(pre, post) },
  {
    name: 'terminal-states-stay',
    pred: (pre, a, d, post) =>
      !['declined', 'failed', 'voided', 'refunded'].includes(pre.status) || (pre.status === post.status && pre.refunded === post.refunded && pre.captured === post.captured),
  },
];

