'use strict';

// SAM v2 strict-profile spec of one payment in src/host.impl.ts.
// status 'none' stands for "no payment with this id" (payment() === null).
// pending counts this payment's authorisation requests not yet completed;
// they are interchangeable, so COMPLETE answers any one of them.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const MAX_REQUESTS = 3;
const INITIAL_STATE = { status: 'none', authorized: 0, captured: 0, refunded: 0, requests: 0, pending: 0 };
const AMOUNTS = [{ amount: 0 }, { amount: 1 }, { amount: 2 }, { amount: 3 }];
const amountSchema = { amount: { type: 'number' } };
const isUnit = (a) => a === 1 || a === 2;

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      status: { type: 'string' },
      authorized: { type: 'number' },
      captured: { type: 'number' },
      refunded: { type: 'number' },
      requests: { type: 'number' },
      pending: { type: 'number' },
