const amountSchema = { amount: { type: 'number' } };
const CAPTURE_AMOUNTS = [{ amount: 0 }, { amount: 1 }, { amount: 2 }, { amount: 3 }, { amount: 4 }];
const MAX_AUTHORIZED = 3;
const isUnit = (a) => a === 1 || a === 2;
const isCaptureAmount = (a) => a === 1 || a === 2 || a === 3;

