      CAPTURE: { action: (data = {}) => ({ ...data }), schema: amountSchema, domain: CAPTURE_AMOUNTS },
      VOID: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      INCREASE: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      REFUND: { action: (data = {}) => ({ ...data }), schema: amountSchema, domain: AMOUNTS },
    },
