test('increase refused unless authorized and uncaptured', async () => {
  const h = await createHost();
  assert.equal((await h.increase('p')).ok, false);
  await h.authorize('p', 1);
  assert.equal((await h.increase('p')).ok, false);
  const [e] = await h.pendingEffects();
  await h.completeEffect(e.id, 'ok');
  await h.capture('p', 1);
  assert.equal((await h.increase('p')).ok, false);
  const v = await createHost();
  await v.authorize('p', 2);
  await v.completeEffect((await v.pendingEffects())[0].id, 'ok');
  await v.void('p');
  assert.equal((await v.increase('p')).ok, false);
  assert.equal((await v.payment('p'))!.authorized, 2);
