  const h = await createHost();
  assert.equal((await h.expire('p')).ok, false);
  await h.authorize('p', 1);
  assert.equal((await h.expire('p')).ok, false);
  await h.timedOut('p');
  const [a, b] = await h.pendingEffects();
  await h.completeEffect(a.id, 'ok');
  await h.increase('p');
  assert.deepEqual(await h.expire('p'), { ok: true });
  const view = { status: 'expired', authorized: 2, captured: 0, refunded: 0, requests: 2 };
  assert.deepEqual(await h.payment('p'), view);
