'use strict';

// SAM v2 strict-profile spec of one payment in src/host.impl.ts.
// status 'none' stands for "no payment with this id" (payment() === null).
// pending counts this payment's authorisation requests not yet completed;
// they are interchangeable, so COMPLETE answers any one of them.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const MAX_REQUESTS = 3;
const INITIAL_STATE = { status: 'none', authorized: 0, captured: 0, refunded: 0, requests: 0, pending: 0 };
const AMOUNTS = [{ amount: 0 }, { amount: 1 }, { amount: 2 }, { amount: 3 }];
const amountSchema = { amount: { type: 'number' } };
const CAPTURE_AMOUNTS = [{ amount: 0 }, { amount: 1 }, { amount: 2 }, { amount: 3 }, { amount: 4 }];
const MAX_AUTHORIZED = 3;
const isUnit = (a) => a === 1 || a === 2;
const isCaptureAmount = (a) => a === 1 || a === 2 || a === 3;

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      status: { type: 'string' },
      authorized: { type: 'number' },
      captured: { type: 'number' },
      refunded: { type: 'number' },
      requests: { type: 'number' },
      pending: { type: 'number' },
    },
    actions: {
      AUTHORIZE: { action: (data = {}) => ({ ...data }), schema: amountSchema, domain: AMOUNTS },
      TIMED_OUT: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      COMPLETE: {
        action: (data = {}) => ({ ...data }),
        schema: { outcome: { type: 'string' } },
        domain: [{ outcome: 'ok' }, { outcome: 'failed' }],
      },
      CAPTURE: { action: (data = {}) => ({ ...data }), schema: amountSchema, domain: CAPTURE_AMOUNTS },
      VOID: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      INCREASE: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      EXPIRE: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      REFUND: { action: (data = {}) => ({ ...data }), schema: amountSchema, domain: AMOUNTS },
    },
    acceptors: {
      AUTHORIZE: (model) => (proposal, { reject, next, unchanged }) => {
        if (!isUnit(proposal.amount)) return reject('invalid-amount');
        if (model.status !== 'none') return reject('payment-exists');
        next.status = 'authorizing';
        next.authorized = proposal.amount;
        next.requests = 1;
        next.pending = 1;
        unchanged('captured', 'refunded');
      },
      TIMED_OUT: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status === 'none') return reject('unknown-payment');
        if (model.status !== 'authorizing') return reject('not-authorizing');
        if (model.requests >= MAX_REQUESTS) {
          next.status = 'failed';
          unchanged('authorized', 'captured', 'refunded', 'requests', 'pending');
          return;
        }
        next.requests = model.requests + 1;
        next.pending = model.pending + 1;
        unchanged('status', 'authorized', 'captured', 'refunded');
      },
      COMPLETE: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.pending === 0) return reject('no-pending-effect');
        next.pending = model.pending - 1;
        if (model.status === 'authorizing') next.status = proposal.outcome === 'ok' ? 'authorized' : 'declined';
        else unchanged('status');
        unchanged('authorized', 'captured', 'refunded', 'requests');
      },
      CAPTURE: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status === 'none') return reject('unknown-payment');
        if (!isCaptureAmount(proposal.amount)) return reject('invalid-amount');
        if (model.status !== 'authorized') return reject('not-authorized');
        if (proposal.amount > model.authorized) return reject('exceeds-authorized');
        next.status = 'captured';
        next.captured = proposal.amount;
        unchanged('authorized', 'refunded', 'requests', 'pending');
      },
      VOID: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status === 'none') return reject('unknown-payment');
        if (model.status !== 'authorized' || model.captured !== 0) return reject('not-voidable');
        next.status = 'voided';
        unchanged('authorized', 'captured', 'refunded', 'requests', 'pending');
      },
      INCREASE: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status === 'none') return reject('unknown-payment');
        if (model.status !== 'authorized' || model.captured !== 0) return reject('not-increasable');
        if (model.authorized >= MAX_AUTHORIZED) return reject('at-max-authorized');
        next.authorized = model.authorized + 1;
        unchanged('status', 'captured', 'refunded', 'requests', 'pending');
      },
      EXPIRE: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status === 'none') return reject('unknown-payment');
        if (model.status !== 'authorized' || model.captured !== 0) return reject('not-expirable');
        next.status = 'expired';
        unchanged('authorized', 'captured', 'refunded', 'requests', 'pending');
      },
      REFUND: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status === 'none') return reject('unknown-payment');
        if (!isUnit(proposal.amount)) return reject('invalid-amount');
        if (model.status !== 'captured') return reject('not-captured');
        if (model.refunded + proposal.amount > model.captured) return reject('exceeds-captured');
        const refunded = model.refunded + proposal.amount;
        next.refunded = refunded;
        if (refunded === model.captured) next.status = 'refunded';
        else unchanged('status');
        unchanged('authorized', 'captured', 'requests', 'pending');
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  AUTHORIZE: (data = {}) => intents.AUTHORIZE(data),
  TIMED_OUT: (data = {}) => intents.TIMED_OUT(data),
  COMPLETE: (data = {}) => intents.COMPLETE(data),
  CAPTURE: (data = {}) => intents.CAPTURE(data),
  VOID: (data = {}) => intents.VOID(data),
  INCREASE: (data = {}) => intents.INCREASE(data),
  EXPIRE: (data = {}) => intents.EXPIRE(data),
  REFUND: (data = {}) => intents.REFUND(data),
};

module.exports = { instance, init, actions, getState, setState };

// The brief's rules, as invariants over one payment.
const UNIT = (a) => a === 1 || a === 2;
const UP_TO_3 = (a) => a === 1 || a === 2 || a === 3;

export const stateInvariants = [
  { name: 'captured-within-authorized', pred: (s) => s.captured <= s.authorized },
  { name: 'refunded-within-captured', pred: (s) => s.refunded <= s.captured },
  { name: 'voided-captured-nothing', pred: (s) => s.status !== 'voided' || (s.captured === 0 && s.refunded === 0) },
  { name: 'at-most-3-requests', pred: (s) => s.requests <= 3 },
  { name: 'pending-within-requests', pred: (s) => s.pending >= 0 && s.pending <= s.requests },
  { name: 'exists-iff-requested', pred: (s) => (s.status === 'none') === (s.requests === 0) },
  { name: 'authorized-1-to-3', pred: (s) => s.status === 'none' || UP_TO_3(s.authorized) },
  { name: 'nothing-moved-before-capture', pred: (s) => ['captured', 'refunded'].includes(s.status) || (s.captured === 0 && s.refunded === 0) },
  { name: 'captured-status-has-capture', pred: (s) => !['captured', 'refunded'].includes(s.status) || UP_TO_3(s.captured) },
  { name: 'refunded-means-all-refunded', pred: (s) => s.status !== 'refunded' || s.refunded === s.captured },
  { name: 'captured-means-not-all-refunded', pred: (s) => s.status !== 'captured' || s.refunded < s.captured },
  { name: 'failed-only-after-3', pred: (s) => s.status !== 'failed' || s.requests === 3 },
  { name: 'raised-only-once-approved', pred: (s) => s.authorized <= 2 || ['authorized', 'captured', 'voided', 'refunded', 'expired'].includes(s.status) },
  { name: 'expired-captured-nothing', pred: (s) => s.status !== 'expired' || (s.captured === 0 && s.refunded === 0) },
];

const changed = (pre, post) => Object.keys(pre).some((k) => pre[k] !== post[k]);

export const transitionInvariants = [
  {
    name: 'authorized-only-raised-by-increase',
    pred: (pre, a, d, post) =>
      pre.status === 'none' || post.authorized === pre.authorized
      || (a === 'INCREASE' && pre.status === 'authorized' && pre.captured === 0 && post.authorized === pre.authorized + 1 && post.authorized <= 3),
  },
  { name: 'increase-changes-only-authorized', pred: (pre, a, d, post) => a !== 'INCREASE' || Object.keys(pre).every((k) => k === 'authorized' || pre[k] === post[k]) },
  { name: 'refunds-only-grow', pred: (pre, a, d, post) => post.refunded >= pre.refunded },
  { name: 'requests-step-by-one', pred: (pre, a, d, post) => post.requests - pre.requests <= 1 && post.requests >= pre.requests },
  {
    name: 'requests-only-from-authorize-or-timeout',
    pred: (pre, a, d, post) => post.requests === pre.requests || a === 'AUTHORIZE' || a === 'TIMED_OUT',
  },
  {
    name: 'provider-decides-only-authorizing',
    pred: (pre, a, d, post) =>
      !['authorized', 'declined'].includes(post.status) || post.status === pre.status || (pre.status === 'authorizing' && a === 'COMPLETE'),
  },
  {
    name: 'invalid-amount-changes-nothing',
    pred: (pre, a, d, post) => !('amount' in (d || {})) || (a === 'CAPTURE' ? UP_TO_3 : UNIT)(d.amount) || !changed(pre, post),
  },
  {
    name: 'terminal-states-stay',
    pred: (pre, a, d, post) =>
      !['declined', 'failed', 'voided', 'refunded', 'expired'].includes(pre.status) || !changed({ ...pre, pending: 0 }, { ...post, pending: 0 }),
  },
  {
    name: 'expires-only-from-authorized-uncaptured',
    pred: (pre, a, d, post) => post.status !== 'expired' || pre.status === 'expired' || (a === 'EXPIRE' && pre.status === 'authorized' && pre.captured === 0),
  },
  { name: 'expired-accepts-no-command', pred: (pre, a, d, post) => pre.status !== 'expired' || a === 'COMPLETE' || !changed(pre, post) },
];

