// Captures replay traces from the real implementation: drives src/host.impl.ts
// through the host interface and records one window per command, projected on
// the contract's state keys for payment 'p'.
//   node spec/capture.ts   -> spec/traces/*.ndjson
import { mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import createHost from '../src/host.impl.ts';
import type { Host } from '../host.ts';

const P = 'p';
type Step = { action: string; data: Record<string, unknown> };

const observe = async (h: Host) => {
  const v = await h.payment(P);
  const pending = (await h.pendingEffects()).filter((e) => e.from === P).length;
  if (!v) return { status: 'none', authorized: 0, captured: 0, refunded: 0, requests: 0, pending };
  return { status: v.status, authorized: v.authorized, captured: v.captured, refunded: v.refunded, requests: v.requests, pending };
};

const apply = async (h: Host, { action, data }: Step) => {
  const amount = data.amount as number;
  switch (action) {
    case 'AUTHORIZE': return h.authorize(P, amount);
    case 'TIMED_OUT': return h.timedOut(P);
    case 'CAPTURE': return h.capture(P, amount);
    case 'VOID': return h.void(P);
    case 'INCREASE': return h.increase(P);
    case 'EXPIRE': return h.expire(P);
    case 'REFUND': return h.refund(P, amount);
    case 'COMPLETE': {
      const e = (await h.pendingEffects()).find((x) => x.from === P);
      if (e) await h.completeEffect(e.id, data.outcome as 'ok' | 'failed');
      return;
    }
  }
};

const run = async (steps: Step[]) => {
  const h = await createHost();
  const lines: string[] = [];
  for (const step of steps) {
    const pre = await observe(h);
    await apply(h, step);
    lines.push(JSON.stringify({ pre, action: step.action, data: step.data, post: await observe(h) }));
  }
  return lines.join('\n') + '\n';
};

const S = (action: string, data: Record<string, unknown> = {}): Step => ({ action, data });
const scenarios: Record<string, Step[]> = {
  happy: [S('AUTHORIZE', { amount: 2 }), S('COMPLETE', { outcome: 'ok' }), S('CAPTURE', { amount: 2 }), S('REFUND', { amount: 1 }), S('REFUND', { amount: 1 }), S('REFUND', { amount: 1 })],
  declined: [S('CAPTURE', { amount: 1 }), S('AUTHORIZE', { amount: 3 }), S('AUTHORIZE', { amount: 1 }), S('AUTHORIZE', { amount: 1 }), S('COMPLETE', { outcome: 'failed' }), S('COMPLETE', { outcome: 'ok' }), S('CAPTURE', { amount: 1 })],
  retries: [S('AUTHORIZE', { amount: 1 }), S('TIMED_OUT'), S('TIMED_OUT'), S('TIMED_OUT'), S('TIMED_OUT'), S('COMPLETE', { outcome: 'ok' }), S('COMPLETE', { outcome: 'ok' }), S('COMPLETE', { outcome: 'ok' }), S('COMPLETE', { outcome: 'ok' })],
  lateAnswer: [S('AUTHORIZE', { amount: 2 }), S('TIMED_OUT'), S('COMPLETE', { outcome: 'ok' }), S('COMPLETE', { outcome: 'failed' }), S('VOID'), S('VOID'), S('CAPTURE', { amount: 1 })],
  captureLimits: [S('AUTHORIZE', { amount: 1 }), S('COMPLETE', { outcome: 'ok' }), S('CAPTURE', { amount: 2 }), S('CAPTURE', { amount: 0 }), S('CAPTURE', { amount: 1 }), S('VOID'), S('REFUND', { amount: 2 }), S('REFUND', { amount: 1 })],
  increase: [S('INCREASE'), S('AUTHORIZE', { amount: 1 }), S('INCREASE'), S('COMPLETE', { outcome: 'ok' }), S('INCREASE'), S('INCREASE'), S('INCREASE'), S('CAPTURE', { amount: 4 }), S('CAPTURE', { amount: 3 }), S('INCREASE'), S('REFUND', { amount: 3 }), S('REFUND', { amount: 2 }), S('REFUND', { amount: 2 }), S('REFUND', { amount: 1 })],
  increaseThenVoid: [S('AUTHORIZE', { amount: 2 }), S('COMPLETE', { outcome: 'ok' }), S('INCREASE'), S('CAPTURE', { amount: 3 }), S('VOID'), S('INCREASE')],
  expire: [S('EXPIRE'), S('AUTHORIZE', { amount: 1 }), S('TIMED_OUT'), S('EXPIRE'), S('COMPLETE', { outcome: 'ok' }), S('INCREASE'), S('EXPIRE'), S('EXPIRE'), S('CAPTURE', { amount: 1 }), S('VOID'), S('INCREASE'), S('REFUND', { amount: 1 }), S('TIMED_OUT'), S('AUTHORIZE', { amount: 1 }), S('COMPLETE', { outcome: 'failed' })],
  capturedNoExpire: [S('AUTHORIZE', { amount: 2 }), S('COMPLETE', { outcome: 'ok' }), S('CAPTURE', { amount: 1 }), S('EXPIRE'), S('REFUND', { amount: 1 }), S('EXPIRE')],
  partial: [S('AUTHORIZE', { amount: 2 }), S('COMPLETE', { outcome: 'ok' }), S('CAPTURE', { amount: 1 }), S('CAPTURE', { amount: 1 }), S('REFUND', { amount: 2 }), S('REFUND', { amount: 1 }), S('TIMED_OUT')],
};

// Seeded random walks over the contract's (action, data) domain.
const DOMAIN: Step[] = [
  ...[0, 1, 2, 3].flatMap((amount) => ['AUTHORIZE', 'CAPTURE', 'REFUND'].map((a) => S(a, { amount }))),
  S('CAPTURE', { amount: 4 }), S('TIMED_OUT'), S('VOID'), S('INCREASE'), S('INCREASE'), S('EXPIRE'), S('COMPLETE', { outcome: 'ok' }), S('COMPLETE', { outcome: 'failed' }),
];
let seed = 12345;
const rand = (n: number) => { seed = (seed * 1103515245 + 12345) % 2147483648; return (seed >>> 16) % n; };
for (let i = 0; i < 40; i++) {
  const prefix = [S('AUTHORIZE', { amount: 1 + (i % 2) }), ...(i % 4 < 2 ? [S('COMPLETE', { outcome: 'ok' })] : [])];
  scenarios[`walk${i}`] = [...prefix, ...Array.from({ length: 15 }, () => DOMAIN[rand(DOMAIN.length)])];
}

const out = join(dirname(fileURLToPath(import.meta.url)), 'traces');
rmSync(out, { recursive: true, force: true });
mkdirSync(out, { recursive: true });
for (const [name, steps] of Object.entries(scenarios)) writeFileSync(join(out, `${name}.ndjson`), await run(steps));
console.log(`wrote ${Object.keys(scenarios).length} traces to ${out}`);
